const lines = FILE_CONTENT.split('\n');
const names = lines.filter(l => /^src\/|^CMakeLists/.test(l) && !/CONFLICT|Auto-merging/.test(l));
const content = lines.filter(l => l.includes('CONFLICT (content)'));
const moddel = lines.filter(l => l.includes('CONFLICT (modify/delete)'));
const automerged = lines.filter(l => l.startsWith('Auto-merging') && !content.some(c => c.includes(l.replace('Auto-merging ', '').trim())));
console.log('conflicted files (unique):', names.length);
console.log('content conflicts:', content.length, '| modify/delete conflicts:', moddel.length);
console.log('auto-merged OK:', lines.filter(l => l.startsWith('Auto-merging')).length - content.length - moddel.length);
console.log('--- conflict-free auto-merged files ---');
lines.filter(l => l.startsWith('Auto-merging')).forEach(l => {
  const f = l.replace('Auto-merging ', '');
  const bad = lines.some(x => x.includes('CONFLICT') && x.includes(f));
  if (!bad) console.log('  ' + f);
});

