			return last_engine;
		}
		return first_engine;
	} else {
		if (u == head) {
			if (u->IsEngine()) {
				return INVALID_ENGINE;
			}
		}
		if (first_engine != INVALID_ENGINE) {
			return first_engine;
		}
		return last_engine;
	}
	return INVALID_ENGINE;
}

/**
 * Recalculates the cached stuff of a train. Should be called each time a vehicle is added
 * to/removed from the chain, and when the game is loaded.
 * Note: this needs to be called too for 'wagon chains' (in the depot, without an engine)
 * @param allowed_changes Stuff that is allowed to change.
 * @return if changes are allowed after CCF_CHECK_ONLY mode
 */
bool Train::ConsistChanged(ConsistChangeFlags allowed_changes)
{
	uint16 max_speed = UINT16_MAX;

	assert(this->IsFrontEngine() || this->IsFreeWagon() || this->IsFrontWagon());

	this->gcache.cached_total_length = 0;
	this->compatible_railtypes = RAILTYPES_NONE;

	bool train_can_tilt = true;

	for (Train *u = this; u != nullptr; u = u->Next()) {
		const RailVehicleInfo *rvi_u = RailVehInfo(u->engine_type);
		assert(u->First() == this);

		if (allowed_changes & CCF_IMMUTABLE) {
			u->first_engine_type = ConsistFirstEngine(this, u);
		}
		u->gcache.first_engine = u->first_engine_type;

		u->railtype = rvi_u->railtype;

		/* Set user defined data to its default value */
		u->tcache.user_def_data = rvi_u->user_def_data;
		this->InvalidateNewGRFCache();
		u->InvalidateNewGRFCache();
	}

	for (Train *u = this; u != nullptr; u = u->Next()) {
		/* Update user defined data (must be done before other properties) */
		u->tcache.user_def_data = GetVehicleProperty(u, PROP_TRAIN_USER_DATA, u->tcache.user_def_data);
		this->InvalidateNewGRFCache();
		u->InvalidateNewGRFCache();
	}

	if (allowed_changes & CCF_IMMUTABLE) {
		for (Train *u = this; u != nullptr; u = u->Next()) {
			StoreImmutableVariables(u);
		}
	}

	for (Train *u = this; u != nullptr; u = u->Next()) {
		const Engine *e_u = u->GetEngine();
		const RailVehicleInfo *rvi_u = &e_u->u.rail;
		const RailVehicleInfo *rvi_v = u->gcache.first_engine == INVALID_ENGINE ? rvi_u : RailVehInfo(u->gcache.first_engine);

		if (!HasBit(e_u->info.misc_flags, EF_RAIL_TILTS)) train_can_tilt = false;

		/* Cache wagon override sprite group. nullptr is returned if there is none */
		u->tcache.cached_override = GetWagonOverrideSpriteSet(u->engine_type, u->cargo_type, u->gcache.first_engine);

		/* Reset colour map */
		u->colourmap = PAL_NONE;

		/* Update powered-wagon-status and visual effect */
		u->UpdateVisualEffect(true);

		if (rvi_v->pow_wag_power != 0 && rvi_u->railveh_type == RAILVEH_WAGON &&
				UsesWagonOverride(u) && !HasBit(u->vcache.cached_vis_effect, VE_DISABLE_WAGON_POWER)) {
			/* wagon is powered */
			SetBit(u->flags, VRF_POWEREDWAGON); // cache 'powered' status
		} else {
			ClrBit(u->flags, VRF_POWEREDWAGON);
		}

		/* Do not count powered wagons for the compatible railtypes, as wagons always
		   have railtype normal */
		if (rvi_u->power > 0) {
			this->compatible_railtypes |= GetRailTypeInfo(u->railtype)->powered_railtypes;
		}

		if (!u->IsArticulatedPart()) {

			/* Some electric engines can be allowed to run on normal rail. It happens to all
			 * existing electric engines when elrails are disabled and then re-enabled */
			if (HasBit(u->flags, VRF_EL_ENGINE_ALLOWED_NORMAL_RAIL)) {
				u->railtype = RAILTYPE_RAIL;
				u->compatible_railtypes |= RAILTYPES_RAIL;
			}

			const Train *t = u->GetMainArticulatedPart();
			/* max speed is the minimum of the speed limits of all vehicles in the consist */
			if ((t->GetEngine()->u.rail.railveh_type != RAILVEH_WAGON || _settings_game.vehicle.wagon_speed_limits) && !UsesWagonOverride(t)) {
				//const Train *t = this->GetMainArticulatedPart();
				uint16 speed = GetVehicleProperty(t, PROP_TRAIN_SPEED, t->GetEngine()->u.rail.max_speed);
				if (speed != 0) max_speed = min(speed, max_speed);
			}
		}

		uint16 new_cap = e_u->DetermineCapacity(u);
		if (allowed_changes & CCF_CAPACITY) {
			if (!(allowed_changes & CCF_CHECK_ONLY)) {
				/* Update vehicle capacity. */
				if (u->cargo_cap > new_cap) u->cargo.Truncate(new_cap);
				u->refit_cap = min(new_cap, u->refit_cap);
				u->cargo_cap = new_cap;
			}
		} else {
			/* Verify capacity hasn't changed. */
			if (allowed_changes & CCF_CHECK_ONLY) {
				if (new_cap != u->cargo_cap) return false;
			} else if (new_cap != u->cargo_cap) ShowNewGrfVehicleError(u->engine_type, STR_NEWGRF_BROKEN, STR_NEWGRF_BROKEN_CAPACITY, GBUG_VEH_CAPACITY, true);
		}
		u->vcache.cached_cargo_age_period = GetVehicleProperty(u, PROP_TRAIN_CARGO_AGE_PERIOD, e_u->info.cargo_age_period);

		/* check the vehicle length (callback) */
		uint16 veh_len = CALLBACK_FAILED;
		if (e_u->GetGRF() != nullptr && e_u->GetGRF()->grf_version >= 8) {
			/* Use callback 36 */
			veh_len = GetVehicleProperty(u, PROP_TRAIN_SHORTEN_FACTOR, CALLBACK_FAILED);

			if (veh_len != CALLBACK_FAILED && veh_len >= VEHICLE_LENGTH) {
				ErrorUnknownCallbackResult(e_u->GetGRFID(), CBID_VEHICLE_LENGTH, veh_len);
			}
		} else if (HasBit(e_u->info.callback_mask, CBM_VEHICLE_LENGTH)) {
			/* Use callback 11 */
			veh_len = GetVehicleCallback(CBID_VEHICLE_LENGTH, 0, 0, u->engine_type, u);
		}
		if (veh_len == CALLBACK_FAILED) veh_len = rvi_u->shorten_factor;
		veh_len = VEHICLE_LENGTH - Clamp(veh_len, 0, VEHICLE_LENGTH - 1);

		if (allowed_changes & CCF_LENGTH) {
			if (!(allowed_changes & CCF_CHECK_ONLY)) {
				/* Update vehicle length. */
				u->gcache.cached_veh_length = veh_len;
			}
		} else {
			/* Verify length hasn't changed. */
			if (allowed_changes & CCF_CHECK_ONLY) {
				if (veh_len != u->gcache.cached_veh_length) return false;
			} else if (veh_len != u->gcache.cached_veh_length) VehicleLengthChanged(u);
		}

		this->gcache.cached_total_length += u->gcache.cached_veh_length;
		this->InvalidateNewGRFCache();
		u->InvalidateNewGRFCache();
	}

	/* store consist weight/max speed in cache */
	this->vcache.cached_max_speed = max_speed;
	this->tcache.cached_tilt = train_can_tilt;
	this->tcache.cached_max_curve_speed = this->GetCurveSpeedLimit();

	/* recalculate cached weights and power too (we do this *after* the rest, so it is known which wagons are powered and need extra weight added) */
	this->CargoChanged();

	if (this->IsPrimaryVehicle()) {
		this->UpdateAcceleration();
		SetWindowDirty(WC_VEHICLE_DETAILS, this->index);
		InvalidateWindowData(WC_VEHICLE_REFIT, this->index, VIWD_CONSIST_CHANGED);
		InvalidateWindowData(WC_VEHICLE_ORDERS, this->index, VIWD_CONSIST_CHANGED);
		InvalidateNewGRFInspectWindow(GSF_TRAINS, this->index);
	}
	return true;
}

