			if (t->IsMultiheaded()) {
				if (multihead_front) {
					return pos;
				}
				multihead_front = true;
			}
			if (has_wagons) {
				engines_back++;
			} else {
				engines_front++;
			}
		} else {
			has_wagons = true;
		}
	}
	if (engines_front > 0 && has_wagons) return engines_front;
	if (engines_back > 0 && has_wagons) return CountVehiclesInChain(v) - engines_back;
	return 1;
}
