+void ReverseTrainArticulated(Train *v)
+{
+	for (Train *t = v; t != nullptr; t = t->GetNextVehicle()) {
+		if (t->HasArticulatedPart()) {
+			Train *a = t->GetLastEnginePart();
+			a->ClearArticulatedPart();
+			t->SetArticulatedPart();
+			if (t->IsEngine()) {
