+	Train *new_first = v->Last();
+	Train *tmp = v;
+	Train *tmp2 = nullptr;
+	for (Train *a = v->Next(); a != nullptr; a = a->Next()) {
+		tmp->SetNext(tmp2);
+		tmp2 = tmp;
+		tmp = a;
+	}
+	tmp->SetNext(tmp2);
+
+	return new_first;
+}
