bool FindSafePositionProc(TileIndex tile, Trackdir td)
{
	if (IsSafeWaitingPosition(Yapf().GetVehicle(), tile, td, true, !TrackFollower::Allow90degTurns())) {
		this->res_dest_tile = tile;
		this->res_dest_td = td;
