template <class Types>
class CYapfFollowCoupleRailT : public CYapfReserveTrack<Types> {
public:
	typedef typename Types::Tpf Tpf;                     ///< the pathfinder class (derived from THIS class)
	typedef typename Types::TrackFollower TrackFollower;
	typedef typename Types::NodeList::Item Node;        ///< this will be our node type
	typedef typename Node::Key Key;                      ///< key to hash tables

protected:
	/** @copydoc CYapfBaseT::Yapf */
	inline Tpf &Yapf()
	{
		return *static_cast<Tpf *>(this);
	}

public:
	/**
	 * Called by YAPF to move from the given node to the next tile. For each
	 *  reachable trackdir on the new tile creates new node, initializes it
	 *  and adds it to the open list by calling Yapf().AddNewNode(n)
	 */
	inline void PfFollowNode(Node &old_node)
	{
		TrackFollower F(Yapf().GetVehicle(), Yapf().GetCompatibleRailTypes());
		if (F.Follow(old_node.GetLastTile(), old_node.GetLastTrackdir())) {
			Yapf().AddMultipleNodes(&old_node, F);
		}
	}

	/** Return debug report character to identify the transportation type */
	inline char TransportTypeChar() const
	{
		return 't';
	}

	static Trackdir stFindNearestCoupleTrain(const Train *v, bool dont_reserve)
	{
		/* Create pathfinder instance */
		Tpf pf1;
		Trackdir result1;
		if (_debug_desync_level < 2) {
			pf1.DisableCache(true);
			result1 = pf1.FindNearestCoupleTrain(v, dont_reserve);
		} else {
			Trackdir result2 = pf1.FindNearestCoupleTrain(v, true);
			Tpf pf2;
			pf2.DisableCache(true);
			result1 = pf2.FindNearestCoupleTrain(v, dont_reserve);
			if (result1 != result2) {
				DEBUG(desync, 2, "CACHE ERROR: FindSafeTile() = [%s, %s]", result2 ? "T" : "F", result1 ? "T" : "F");
				DumpState(pf1, pf2);
			}
		}

		return result1;
	}

	Trackdir FindNearestCoupleTrain(const Train *v, bool dont_reserve)
	{
		PBSTileInfo origin = FollowTrainReservation(v);
		/* Set origin and destination. */
		Yapf().SetOrigin(origin.tile, origin.trackdir);
		Yapf().SetDestination(v);

		bool path_found = Yapf().FindPath(v);
		if (!path_found) return INVALID_TRACKDIR;

		/* Found a destination, set as reservation target. */
		Node *pNode = Yapf().GetBestNode();
		this->SetReservationTarget(pNode, pNode->GetLastTile(), pNode->GetLastTrackdir());

		/* Walk through the path back to the origin. */
		Trackdir next_trackdir = INVALID_TRACKDIR;
		Node *pPrev = nullptr;
		while (pNode->parent != nullptr) {
			pPrev = pNode;
			pNode = pNode->parent;

			if (!this->CheckSafePositionOnNode(pPrev)) return INVALID_TRACKDIR;
		}

		next_trackdir = pPrev->GetTrackdir();
		if (!dont_reserve) {
			return this->TryReservePath(nullptr, pNode->GetLastTile(), true) ? next_trackdir : INVALID_TRACKDIR;
		}

		return next_trackdir;
	}
};

