		HT_RECT,              // OPOS_COND_VIA
		HT_RECT,              // OPOS_COND_STATION
		HT_NONE,              // OPOS_CONDITIONAL_RETARGET
		HT_RECT,              // OPOS_DEPARTURE_VIA
	};
	SetObjectToPlaceWnd(ANIMCURSOR_PICKSTATION, PAL_NONE, goto_place_style[type - 1], this);
