struct CargoTypesWindow : public Window {
	CargoID sel;
	Scrollbar *vscroll;          ///< The main scrollbar.
	VehicleOrderID order;        ///< If not #INVALID_VEH_ORDER_ID, selection is part of a refit order (rather than execute directly).

	CargoTypesWindow(WindowDesc *desc, const Vehicle *v, VehicleOrderID order) : Window(desc)
	{
		this->sel = CT_COUPLE_ANY_CARGO;
		this->order = order;
		this->CreateNestedTree();

		this->vscroll = this->GetScrollbar(WID_VCT_SCROLLBAR);
		NWidgetCore *nwi = this->GetWidget<NWidgetCore>(WID_VCT_SET);
		nwi->widget_data = STR_TRAIN_CARGOS_CONFIRM + v->type;
		nwi->tool_tip    = STR_REFIT_TRAIN_REFIT_TOOLTIP + v->type;

		this->FinishInitNested(v->index);
		this->owner = v->owner;	

		this->SetWidgetDisabledState(WID_VCT_SET, this->sel == CT_COUPLE_ANY_CARGO);		
	}

	virtual void OnInit()
	{
		this->SetWidgetDisabledState(WID_VCT_SET, this->sel == CT_COUPLE_ANY_CARGO);
		this->RefreshScrollbar();

	}

	virtual void OnClick(Point pt, int widget, int click_count)
	{
		switch (widget) {
			case WID_VCT_MATRIX: { // listbox
				this->SetSelection(this->vscroll->GetScrolledRowFromWidget(pt.y, this, WID_VCT_MATRIX));
				this->SetWidgetDisabledState(WID_VCT_SET, this->sel == CT_COUPLE_ANY_CARGO);
				this->RefreshScrollbar();
				this->InvalidateData();

				if (click_count == 1) break;
				FALLTHROUGH;
			}

			case WID_VCT_SET: // set button
				if (this->sel != CT_COUPLE_ANY_CARGO) {
					const Vehicle *v = Vehicle::Get(this->window_number);
					if (DoCommandP(v->tile, v->index + (this->order << 20), MOF_COUPLE_CARGO | (sel << 8), CMD_MODIFY_ORDER | CMD_MSG(STR_ERROR_CAN_T_MODIFY_THIS_ORDER))) delete this;
				}
				break;
		}
	}

	virtual void DrawWidget(const Rect &r, int widget) const
	{
		switch (widget) {

			case WID_VCT_MATRIX:
				DrawVehicleCargoTypeWindow(sel, this->vscroll->GetPosition(), this->vscroll->GetCapacity(), this->resize.step_height, r);
				break;
		}
	}

	void SetSelection(uint click_row)
	{
		uint row = 0;

		CargoSpec *cs;
		FOR_ALL_CARGOSPECS(cs) {
			if (row == click_row) {
				this->sel = click_row;
				return;
			}
			row++;
		}
		this->sel = CT_COUPLE_ANY_CARGO;
	}

	virtual void OnResize()
	{
		this->vscroll->SetCapacityFromWidget(this, WID_VCT_MATRIX);
	}

	virtual void UpdateWidgetSize(int widget, Dimension *size, const Dimension &padding, Dimension *fill, Dimension *resize)
	{
		switch (widget) {
			case WID_VCT_MATRIX:
				resize->height = WD_MATRIX_TOP + FONT_HEIGHT_NORMAL + WD_MATRIX_BOTTOM;
				size->height = resize->height * 8;
				break;
		}
	}

	void RefreshScrollbar()
	{
		uint row = 0;

		CargoSpec *cs;
		FOR_ALL_CARGOSPECS(cs) {
			row++;
		}

		this->vscroll->SetCount(row);
		//if (sel < row) this->vscroll->ScrollTowards(sel);
	}

	virtual void OnPaint()
	{

	{
		this->DrawWidgets();
	}

	virtual void SetStringParameters(int widget) const
	{
		if (widget == WID_VCT_CAPTION) SetDParam(0, Vehicle::Get(this->window_number)->index);
	}


};



