static void DrawVehicleCargoTypeWindow(CargoType sel, uint pos, uint rows, uint delta, const Rect &r)
{
	uint y = r.top + WD_MATRIX_TOP;

	int textleft  = r.left + WD_MATRIX_LEFT;
	int textright = r.right - WD_MATRIX_RIGHT;

