static bool TryTrainCouple(Train *v, Train *u)
{
	TrainList original_src;
	TrainList original_dst;

	MakeTrainBackup(original_src, v);
	MakeTrainBackup(original_dst, u);

	Train *u_head = u;
	Train *v_last = v->Last();
	//ArrangeTrains(Train **dst_head, Train *dst, Train **src_head, Train *src, bool move_chain);
	ArrangeTrains(&v, v_last, &u_head, u, true);

	CommandCost ret = CheckTrainAttachment(v);
	bool ok = v->ConsistChanged(CCF_ARRANGE_CHECK);

	if (ret.Failed() || !ok) {
		/* Restore the train we had. */
		RestoreTrainBackup(original_src);
		RestoreTrainBackup(original_dst);

		v->ConsistChanged(CCF_ARRANGE_STATION);
		u->ConsistChanged(CCF_ARRANGE_STATION);
		return false;
	}
	return true;
}
static void Couple(Train *v, Train *u, bool train_u_reversed)
{
	if (train_u_reversed) {
		ReverseTrainDirection(u);
		/* Reverse swap first and last vehicle */
		u = u->First();
	}
	v->IncrementImplicitOrderIndex();
	ProcessOrders(v);
	ReverseTrainDirection(v);
	v = v->First();

	Train *v_last = v->Last();

	if (!TryTrainCouple(v, u)) {
		if (v->owner == _local_company) {
			SetDParam(0, v->index);
			SetDParam(1, u->index);
			AddVehicleAdviceNewsItem(STR_NEWS_ORDER_COUPLE_FAILED, v->index);
		}
		return;
	}

	/* Delete orders, group stuff and the unit number as we're not the
	 * front of any vehicle anymore. */

	DeleteWindowById(WC_VEHICLE_VIEW, u->index);
	DeleteWindowById(WC_VEHICLE_ORDERS, u->index);
	DeleteWindowById(WC_VEHICLE_REFIT, u->index);
	DeleteWindowById(WC_VEHICLE_DETAILS, u->index);
	DeleteWindowById(WC_VEHICLE_TIMETABLE, u->index);
	DeleteNewGRFInspectWindow(GSF_TRAINS, u->index);
	SetWindowDirty(WC_COMPANY, _current_company);

	DeleteVehicleOrders(u);
	RemoveVehicleFromGroup(u);
	u->unitnumber = 0;
	GroupStatistics::CountVehicle(u, -1);

	v->profit_this_year += u->profit_this_year;
	v->profit_last_year += u->profit_last_year;

	u->profit_last_year = 0;
	u->profit_this_year = 0;

	u->ClearFrontWagon();
	u->ClearFrontEngine();

	NormaliseTrainHead(v, CCF_ARRANGE_STATION);

	AdvanceWagonsAfterCouple(v_last);
	InvalidateWindowClassesData(WC_TRAINS_LIST, 0);
	if (CheckReverseTrain(v)) SetBit(v->flags, VRF_REVERSING);
}

